    Bug 1999538 - Add Content-Type Parameter "hp" from RFC 9788 when sending OpenPGP messages. r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D284336

diff --git a/mail/extensions/openpgp/content/modules/mimeEncrypt.sys.mjs b/mail/extensions/openpgp/content/modules/mimeEncrypt.sys.mjs
index 892bcef00ce..ce65c7d03a5 100644
--- a/mail/extensions/openpgp/content/modules/mimeEncrypt.sys.mjs
+++ b/mail/extensions/openpgp/content/modules/mimeEncrypt.sys.mjs
@@ -185,7 +185,15 @@ PgpMimeEncrypt.prototype = {
     }

     let w = `Content-Type: multipart/mixed; boundary="${this.encHeader}"`;
-    w += `;\r\n protected-headers="v1"\r\n${this.headers}`;
+    w += `;\r\n protected-headers="v1"`;
+    if (this.signMessage) {
+      if (this.requireEncryptMessage) {
+        w += '; hp="cipher"';
+      } else {
+        w += '; hp="clear"';
+      }
+    }
+    w += `\r\n${this.headers}`;

     if (
       (this.mimeStructure == MIME_ENCRYPTED ||
